import re
from typing import List, Dict, Any, Union

# ----------------------------------------------------------------------
# Helper utilities
# ----------------------------------------------------------------------
def _clean_number(s: str) -> Union[float, None]:
    """Convert currency/numeric strings to a float, honoring parentheses for negatives."""
    if not isinstance(s, str):
        return None
    s = s.strip()
    if s in ("", "—", "-"):
        return None

    neg = False
    if s.startswith("(") and s.endswith(")"):
        neg = True
        s = s[1:-1]

    # Remove unrealistic characters
    s = re.sub(r"[^\d.,'\-eE]", "", s)
    if not s:
        return None

    s = s.replace(",", "").replace("'", "")
    try:
        num = float(s)
        return -num if neg else num
    except ValueError:
        return None


def _parse_year(col: str) -> Union[float, None]:
    """Find a four‑digit year in a column name."""
    m = re.search(r"(\d{4})", col)
    return float(m.group(1)) if m else None


# ----------------------------------------------------------------------
# Core model extraction functions
# ----------------------------------------------------------------------
def _node_ids_by_title(doc: dict, title: str) -> List[str]:
    """Return a list of node_ids that match the given title."""
    return [n["node_id"] for n in doc.get("nodes", []) if n.get("title") == title]


def _find_node_by_title(doc: dict, title: str) -> Dict[str, Any]:
    """Return the node dict with the given title, or None."""
    for n in doc.get("nodes", []):
        if n.get("title") == title:
            return n
    return None


def _table_rows(node: Dict[str, Any]):
    """Yield (row_index, {column: cell_string}) from a table node."""
    for row_index, row in enumerate(node.get("table", {}).get("rows", [])):
        yield row_index, dict(zip(node["table"]["columns"], row))


def entities(doc: dict, scope: str) -> List[Dict[str, str]]:
    """
    Return a list of distinct entities referenced in the tables belonging to the given scope.
    Each entity has a unique id and a human‑readable description.
    """
    scope_node = _find_node_by_title(doc, scope)
    if not scope_node:
        return []

    ent_list: List[Dict[str, str]] = []
    seen: set = set()

    # Find the child table node (exact title match)
    table_node = _find_node_by_title(doc, f"{scope}: Table")
    if not table_node or table_node.get("kind") != "table":
        return []

    for row_index, row in _table_rows(table_node):
        # Skip header row(s).  Header rows typically have an empty 'col0'.
        if row_index == 0 or not row.get("col0"):
            continue
        desc = row.get("col0", "").strip()
        if not desc:
            continue
        ent_id = f"{table_node['node_id']}_row{row_index}"
        if ent_id not in seen:
            seen.add(ent_id)
            ent_list.append({"id": ent_id, "description": desc})

    return ent_list


def recorded_end(doc: dict, scope: str) -> Union[float, None]:
    """
    Return the latest year mentioned in any column of the tables in the scope.
    """
    table_node = _find_node_by_title(doc, f"{scope}: Table")
    if not table_node or table_node.get("kind") != "table":
        return None

    max_year: Union[float, None] = None
    for _, row in _table_rows(table_node):
        for col_name in row:
            y = _parse_year(col_name)
            if y is not None:
                if max_year is None or y > max_year:
                    max_year = y
    return max_year


def inputs(doc: dict, scope: str) -> List[Dict[str, Any]]:
    """
    All external inputs – for this synthetic data set, there are no external
    numeric inputs that are not produced by the process, so we return an empty list.
    """
    return []


def outcomes(doc: dict, scope: str) -> List[Dict[str, Any]]:
    """
    Every numeric cell in the table of the scope is treated as an outcome record.
    """
    table_node = _find_node_by_title(doc, f"{scope}: Table")
    if not table_node or table_node.get("kind") != "table":
        return []

    # Build a mapping of entity IDs from entities()
    ent_map = {e["id"]: e["description"] for e in entities(doc, scope)}

    outcomes: List[Dict[str, Any]] = []

    for row_index, row in _table_rows(table_node):
        # Skip header rows that do not represent an entity
        if row_index == 0 or not row.get("col0"):
            continue
        ent_desc = row.get("col0", "").strip()
        if not ent_desc:
            continue
        ent_id = f"{table_node['node_id']}_row{row_index}"
        ent_map.setdefault(ent_id, ent_desc)

        for col_name, cell_value in row.items():
            if col_name == "col0":
                continue
            val = _clean_number(cell_value)
            if val is None:
                continue
            t = _parse_year(col_name)
            outcomes.append({
                "time": t,
                "kind": "amount",
                "entities": [ent_id],
                "value": val,
                "src": [[table_node["node_id"], row_index, [col_name]]],
            })

    return outcomes


def params(doc: dict, scope: str) -> Dict[str, float]:
    """
    Return any named constants that appear within the document.
    For the sample data set there are none.
    """
    return {}
